                    ar_valid            := true.B
                    ar_payload.ID       := 0.U
                    ar_payload.ADDR     := ar_addr
                    ar_payload.LEN      := ar_len
                    ar_payload.SIZE     := ar_size.U
                    ar_payload.BURST    := 1.U
                    ar_payload.LOCK     := false.B
                    ar_payload.CACHE    := 2.U
                    ar_payload.PROT     := 2.U
                }.otherwise {
                    ar_valid            := false.B
                }
            } // sIDLE
            is (sADDR) {
                when (ReadIntf.AR.ready) {
                    ar_valid            := false.B
                }
            } // sADDR
        } // switch(state)

