        DataIntf.valid  := (state === sDATA) && ReadIntf.R.valid
        DataIntf.bits   := ReadIntf.R.bits.DATA

        //
        // Command Interface Ready
        //
        CmdIntf.ready   := state === sIDLE

    } // withClockAndReset(ACLK, reset)

} // class Reader

/**
